def espn_mlb_award(*args, **kwargs):
    """``return_parsed=True`` by default (parsed.* mirror of ``mlb.espn_mlb_award``).

    .. deprecated:: 0.0.54
       Import :func:`sportsdataverse.mlb.espn_mlb_award` directly instead;
       that function now returns a parsed DataFrame by default.

    Pass ``return_parsed=False`` for the raw ``Dict``. See
    :func:`sportsdataverse.mlb.espn_mlb_award` for full documentation.
    """
    kwargs.setdefault("return_parsed", True)
    return _raw_espn_mlb_award(*args, **kwargs)


